import{_ as a,b as o,c as e,I as r}from"./chunks/framework.C6cPs9Ia.js";const u=JSON.parse('{"title":"二次元高中生存指南（血泪版）","description":"二次元高中生的生存指南——如何在学习与热爱之间反复横跳而不翻车","frontmatter":{"title":"二次元高中生存指南（血泪版）","date":"2026-09-13T00:00:00.000Z","tags":["学习","日常","高中"],"cover":"/LQY/images/moment-1.jpg","head":[["meta",{"name":"description","content":"二次元高中生的生存指南——如何在学习与热爱之间反复横跳而不翻车"}],["meta",{"name":"keywords","content":"高中, 生存指南, 学习方法, 二次元日常"}]]},"headers":[],"relativePath":"posts/high-school-survival.md","filePath":"posts/high-school-survival.md"}'),s={name:"posts/high-school-survival.md"};function i(l,t,n,p,h,c){return o(),e("div",null,[...t[0]||(t[0]=[r('<p>白天题海，晚上追番，中间还要给看板娘换装——一个二次元高中生的时间管理，堪比在夹缝里种花。</p><p>这篇把两年血泪换来的生存经验整理成册，开学的新人请收好。</p><hr><h2 id="法则一-主线任务优先级最高" tabindex="-1">法则一：主线任务优先级最高 <a class="header-anchor" href="#法则一-主线任务优先级最高" aria-label="Permalink to &quot;法则一：主线任务优先级最高&quot;">​</a></h2><p>游戏里有主线和支线，高中也有。</p><p><strong>主线：月考、期中、期末，以及那个最终 Boss——高考。</strong><strong>支线：新番、活动、限定卡池、新皮肤。</strong></p><p>支线奖励再香，主线断更就存档丢失。所以我的原则是：<strong>主线推进没问题时，支线随便刷；主线告急时，支线一律封印。</strong></p><p>（上学期封印了两周新番，回来发现攒了三季——幸福的烦恼。）</p><h2 id="法则二-把碎片时间全喂给热爱" tabindex="-1">法则二：把碎片时间全喂给热爱 <a class="header-anchor" href="#法则二-把碎片时间全喂给热爱" aria-label="Permalink to &quot;法则二：把碎片时间全喂给热爱&quot;">​</a></h2><p>正片时间给学习，<strong>碎片时间全给二次元</strong>，一点都不亏：</p><ul><li>课间 10 分钟 → 刷一张新图，给看板娘截一张新壁纸</li><li>通学路 23 分钟 → 歌单循环（见另一篇文章）</li><li>排队打饭 5 分钟 → 追番区更新情报扫一眼</li><li>睡前 15 分钟 → 漫画一话，不多看——多看的下场是凌晨两点</li></ul><h2 id="法则三-物理防御与信息伪装" tabindex="-1">法则三：物理防御与信息伪装 <a class="header-anchor" href="#法则三-物理防御与信息伪装" aria-label="Permalink to &quot;法则三：物理防御与信息伪装&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">家长突袭预警系统</p><ol><li>手机永远开着&quot;学习模式&quot;界面驻守</li><li>平板看番必须戴耳机，且音量 60%</li><li>桌面布局：作业在最上层，立牌靠墙站（他们以为那是普通摆件，其实是我们这边的接头暗号）</li></ol></div><p>不是说和父母为敌。是<strong>先把该做的做完，再理直气壮地玩</strong>——查岗都查不到把柄，这才是最高境界。这学期我月考进步了 11 名，我妈现在看到我&quot;玩电脑&quot;只会默默把门带上。（真事。）</p><h2 id="法则四-找到同类-但别成群结队地摆" tabindex="-1">法则四：找到同类，但别成群结队地摆 <a class="header-anchor" href="#法则四-找到同类-但别成群结队地摆" aria-label="Permalink to &quot;法则四：找到同类，但别成群结队地摆&quot;">​</a></h2><p>班里的二次元浓度检测：开学第一周靠桌面壁纸和笔袋挂件互相识别。</p><p>找到同类的好处：笔记可以互通、新番可以一起蹲、理想可以互相监督。</p><p>但要警惕&quot;集体摆烂&quot;——五个人凑一起聊整晚游戏剧情的爽，第二天早读全会还。<strong>热爱是充电，不是漏电。</strong></p><h2 id="法则五-允许自己偶尔掉线" tabindex="-1">法则五：允许自己偶尔掉线 <a class="header-anchor" href="#法则五-允许自己偶尔掉线" aria-label="Permalink to &quot;法则五：允许自己偶尔掉线&quot;">​</a></h2><p>不是每天都要满效率运转的。考砸的那天，允许自己看一集最爱的番，喝一杯快乐水，什么都不想。</p><p><strong>掉线不可怕，可怕的是从此再也不上线。</strong></p><hr><p>以上，就是本猫窝的生存法则合集。</p><p>祝你也能在自己的世界里，把主线和支线都玩得漂亮。有更好的生存技巧，评论区交出来——本攻略持续更新中。喵。</p>',24)])])}const g=a(s,[["render",i]]);export{u as __pageData,g as default};
